+import { build } from 'esbuild';
+import { writeFileSync } from 'node:fs';
+import { pathToFileURL } from 'node:url';
+
+await build({
+  entryPoints: ['src/analyze.ts'],
+  outfile: '/tmp/analyze.mjs',
+  format: 'esm',
+  bundle: true,
+  platform: 'node',
+  packages: 'external',
+});
+
+const { analyze, extractImports } = await import(pathToFileURL('/tmp/analyze.mjs').href);
+import { dedent } from 'ts-dedent';
+import { parse } from '@babel/parser';
+
+const babelParse = (code) => parse(code, { sourceType: 'module', plugins: ['jsx'] });
+
+const show = (label, v) => console.log(label, JSON.stringify(v));
+
+// 1. basic Meta with title
+show('title', await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+
+  <Meta title="Introduction" />
+
+  # Hello
+`));
+
+// 2. of with identifier
+show('of', await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  import * as ButtonStories from './Button.stories';
+
+  <Meta of={ButtonStories} />
+`));
+
+// 3. tags + isTemplate implicit
+show('tags', await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+
+  <Meta title="T" tags={['autodocs', 'foo']} isTemplate />
+`));
+
+// 4. isTemplate numeric -> error
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta title="T" isTemplate={5} />
+`); console.log('ERR-isTemplate: NO THROW'); }
+catch(e){ console.log('ERR-isTemplate:', e.message); }
+
+// 5. title expression -> error
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta title={foo} />
+`); console.log('ERR-title: NO THROW'); }
+catch(e){ console.log('ERR-title:', e.message); }
+
+// 6. of string literal -> error
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta of="foo" />
+`); console.log('ERR-of: NO THROW'); }
+catch(e){ console.log('ERR-of:', e.message); }
+
+// 7. unknown identifier
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta of={Nope} />
+`); console.log('ERR-unknown: NO THROW'); }
+catch(e){ console.log('ERR-unknown:', e.message); }
+
+// 8. duplicate Meta
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta title="a" />
+  <Meta title="b" />
+`); console.log('ERR-dup: NO THROW'); }
+catch(e){ console.log('ERR-dup:', e.message); }
+
+// 9. no Meta -> defaults
+show('noMeta', await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  # Just content
+`));
+
+// 10. exported declarations
+try { const r = await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  export const foo = 1;
+  <Meta title="Exp" />
+`); show('exports-ok', r); }
+catch(e){ console.log('ERR-exports:', e.message); }
+
+// 11. extractImports directly with babel AST (named + namespace)
+const prog = babelParse(dedent`
+  import { Meta } from '@storybook/blocks';
+  import * as ButtonStories from './Button.stories';
+  import Default from './x';
+`);
+show('extractImports-babel', extractImports(prog));
+
+// 12. malformed MDX
+show('malformed', await analyze('<Meta title=  <<< broken'));
+
+// 13. tags non-string element
+try { await analyze(dedent`
+  import { Meta } from '@storybook/blocks';
+  <Meta tags={[1]} />
+`); console.log('ERR-tag: NO THROW'); }
+catch(e){ console.log('ERR-tag:', e.message); }
